    patterns: [
      "昼寝",
      "寝てた",
      "寝ていた",
      "仮眠",
    ],
  },
  {
    name: "料理",
    patterns: [
      "料理して",
      "ご飯作",
      "ごはん作",
    ],
  },
  {
    name: "掃除",
    patterns: [
      "掃除して",
      "片付けて",
      "片づけて",
    ],
  },
];

function containsAny(
  text: string,
  patterns: string[]
) {
  return patterns.some(
    (pattern) =>
      text.includes(pattern)
  );
}

function findUnsupportedActivityGroups(
  reply: string,
  evidence: ActivityEvidence
) {
  const pastMarkers = [
    "さっき",
    "少し前",
    "帰ってき",
    "帰宅",
    "してた",
    "していた",
    "だった",
    "終わった",
    "済ませ",
    "行ってた",
    "行ってきた",
  ];

  if (
    !containsAny(
      reply,
      pastMarkers
    )
  ) {
    return [];
  }

  return activityGroups
    .filter(
      (group) =>
        containsAny(
          reply,
          group.patterns
        ) &&
        !evidence.texts.some(
          (text) =>
            containsAny(
              text,
              group.patterns
            )
        )
    )
    .map(
      (group) => group.name
    );
}

function createActivityGroundingGuide(
  evidence: ActivityEvidence
) {
  if (
    evidence.texts.length === 0
  ) {
    return `
【美咲自身の過去行動】

現在、
会話履歴にも今日の記憶にも
美咲自身の具体的な過去行動の根拠はありません。

「さっき買い物してた」
「今帰ってきた」
「仕事終わったところ」
「お風呂入ってた」
「ご飯食べてた」
などを新しく作らないでください。
`.trim();
  }

  return `
【美咲自身の過去行動】

具体的な過去行動として
根拠にできるのは次だけです。

${evidence.texts
  .slice(-20)
  .map((text) => `・${text}`)
  .join("\n")}

ここにない別の行動を
新しく過去の事実として
作らないでください。
`.trim();
}

