`
          : "";

      const controller =
        new AbortController();
      const startedAt =
        Date.now();
      const timeout =
        setTimeout(
          () =>
            controller.abort(),
          GEMINI_TIMEOUT_MS
        );

      const attempt =
        retryProblems &&
        retryProblems.length > 0
          ? "retry"
          : "initial";
      const hasSupplementaryUnicode =
        /[\uD800-\uDBFF][\uDC00-\uDFFF]/
