      );

      try {
        const response =
          await fetch(
            `https://generativelanguage.googleapis.com/v1beta/models/gemini-3.1-flash-lite:generateContent?key=${apiKey}`,
            {
              method: "POST",
              headers: {
                "Content-Type":
                  "application/json",
              },
              signal:
                controller.signal,
              body:
                JSON.stringify({
                  systemInstruction: {
                    parts: [
