          {
            traceId,
            attempt,
            status:
              response.status,
            elapsedMs,
          }
        );

        const data =
          await response.json();

        if (!response.ok) {
          console.error(
            "GEMINI API ERROR:",
            {
              traceId,
              attempt,
              status:
                response.status,
              elapsedMs,
              data,
