            ?.content?.parts?.[0]
            ?.text
        );
      } catch (error) {
        const elapsedMs =
          Date.now() -
          startedAt;

        if (
          error instanceof
            Error &&
          error.name ===
            "AbortError"
        ) {
          console.error(
            "GEMINI FETCH TIMEOUT:",
            {
              traceId,
              attempt,
              elapsedMs,
