            ).length > 0
          ) {
            return false;
          }

          if (
            findDayTypeProblems(
              item,
              misakiDayType
            ).length > 0
          ) {
            return false;
          }

          return true;
        }
      );

    const updatedTodayMemory:
      MisakiTodayMemory = {
      date: currentDate,
      items:
        Array.from(
          new Set([
            ...safeTodayMemory.items,
            ...safeNewTodayItems,
          ])
        ).slice(
          -MAX_TODAY_MEMORY
        ),
