function decodeXmlText(
  value: string
) {
  return value
    .replace(
      /&lt;/g,
      "<"
    )
    .replace(
      /&gt;/g,
      ">"
    )
    .replace(
      /&amp;/g,
      "&"
    )
    .replace(
      /&quot;/g,
      '"'
    )
    .replace(
      /&#39;/g,
      "'"
    )
    .replace(
      /&nbsp;/g,
      " "
    );
}

function stripTags(
  value: string
) {
  return decodeXmlText(
    value.replace(
      /<[^>]*>/g,
      " "
    )
  )
    .replace(
      /\s+/g,
      " "
    )
    .trim();
}

function normalizeText(
  value: string
) {
  return value
    .replace(
      /\r/g,
      ""
    )
    .replace(
      /\n+/g,
      " "
    )
    .replace(
      /\s+/g,
      " "
    )
    .trim();
}

function getTag(
  xml: string,
  tag: string
) {
  const pattern =
    new RegExp(
      `<${tag}(?:\\s[^>]*)?>([\\s\\S]*?)<\\/${tag}>`,
      "i"
    );

  const match =
    xml.match(
      pattern
    );

  return match
    ? stripTags(
        match[1]
      )
    : "";
}

function getEntries(
  xml: string
) {
  return (
    xml.match(
      /<entry(?:\s[^>]*)?>[\s\S]*?<\/entry>/gi
    ) ?? []
  );
}

function getLink(
  entry: string
) {
  const match =
    entry.match(
      /<link[^>]+href=["']([^"']+)["'][^>]*\/?>/i
    );

  return (
    match?.[1] ??
    ""
  );
}

async function fetchText(
  url: string,
  revalidate = 300
) {
  try {
    const response =
      await fetch(
        url,
        {
          next: {
            revalidate,
          },

          headers: {
            "User-Agent":
              "Mozilla/5.0",

            "Accept-Language":
              "ja,en;q=0.8",
          },
        }
      );

    if (
      !response.ok
    ) {
      console.error(
        "TOKYO EVENT FETCH ERROR:",
        url,
        response.status
      );

      return null;
    }

    return await response.text();
  } catch (error) {
    console.error(
      "TOKYO EVENT FETCH ERROR:",
      url,
      error
    );

    return null;
  }
}

async function fetchJson<T>(
  url: string,
  revalidate = 300
): Promise<T | null> {
  try {
    const response =
      await fetch(
        url,
        {
          next: {
            revalidate,
          },
        }
      );

    if (
      !response.ok
    ) {
      console.error(
        "WEATHER FORECAST ERROR:",
        response.status
      );

      return null;
    }

    return (
      await response.json()
    ) as T;
  } catch (error) {
    console.error(
      "WEATHER FORECAST ERROR:",
      error
    );

    return null;
  }
}

function isRecent(
  dateText: string,
  maxHours: number
) {
  if (!dateText) {
    return true;
  }

  const time =
    new Date(
      dateText
    ).getTime();

  if (
    !Number.isFinite(
      time
    )
  ) {
    return true;
  }

  return (
    Date.now() -
      time <=
    maxHours *
      60 *
      60 *
      1000
  );
}

