  return (
    normalized.includes(
      "すべて解除"
    ) ||
    normalized.includes(
      "全て解除"
    ) ||
    normalized.includes(
      "警報を解除"
    ) ||
    normalized.includes(
      "注意報を解除"
    ) ||
    normalized.includes(
      "解除しました"
    )
  );
}

function createWarningDetail(
  title: string,
  headline: string
) {
  if (
    title.includes(
      "土砂災害警戒情報"
    )
  ) {
    return (
      headline ||
      "東京都内に土砂災害警戒情報が発表されています。"
    );
  }

  if (
    title.includes(
      "竜巻注意情報"
    )
  ) {
    return (
      headline ||
      "東京都内に竜巻注意情報が発表されています。"
    );
  }

  if (
    title.includes(
      "気象特別警報"
    )
  ) {
    return (
      headline ||
      "東京都内に気象特別警報が発表されています。"
    );
  }

  return (
    headline ||
    "東京都内に気象警報・注意報の情報が発表されています。"
