function hasHanedaDisruption(
  html: string
) {
  const text =
    normalizeText(
      stripTags(
        html
      )
    );

  /*
   * ページ内の固定テンプレート文章ではなく、
   * 現在状態として表示される文章だけを見る。
   */
  return (
    text.includes(
      "現在、一部フライトの運航に乱れが生じています"
    ) ||
    text.includes(
      "Currently, some Flights are experiencing disruptions"
    )
  );
}

async function getHanedaEvents():
  Promise<
    TokyoLifeEvent[]
  > {
  const [
    domesticHtml,
    internationalHtml,
  ] =
    await Promise.all([
      fetchText(
        HANEDA_DOMESTIC_URL,
        180
      ),

      fetchText(
        HANEDA_INTERNATIONAL_URL,
        180
      ),
    ]);

  const domesticProblem =
    domesticHtml
      ? hasHanedaDisruption(
          domesticHtml
        )
      : false;

  const internationalProblem =
    internationalHtml
      ? hasHanedaDisruption(
          internationalHtml
        )
      : false;

  if (
    !domesticProblem &&
    !internationalProblem
  ) {
    return [];
  }

  let detail =
    "";

  if (
    domesticProblem &&
    internationalProblem
  ) {
    detail =
      "羽田空港の国内線・国際線で、一部便の運航に乱れが出ている表示があります。";
  } else if (
    domesticProblem
  ) {
    detail =
      "羽田空港の国内線で、一部便の運航に乱れが出ている表示があります。";
  } else {
    detail =
      "羽田空港の国際線で、一部便の運航に乱れが出ている表示があります。";
  }

  return [
    {
      type:
        "haneda",

      title:
        "羽田空港で一部便に運航の乱れ",

      detail,

      source:
        "羽田空港旅客ターミナル",
    },
  ];
}

/*
 * ===========================
 * 全イベント取得
 * ===========================
 */

export async function getTokyoLifeEvents():
  Promise<
    TokyoLifeEvent[]
  > {
  try {
    const [
      earthquakes,
      warnings,
      weatherForecast,
      trains,
      haneda,
    ] =
      await Promise.all([
        getEarthquakeEvents(),

        getWeatherWarningEvents(),

        getKotoWeatherForecastEvents(),

        getTrainEvents(),

        getHanedaEvents(),
      ]);

    return [
      ...earthquakes,
      ...warnings,
      ...weatherForecast,
      ...trains,
      ...haneda,
    ].slice(
      0,
      MAX_EVENTS
    );
  } catch (error) {
    console.error(
      "TOKYO LIFE EVENTS ERROR:",
      error
    );

    /*
     * 外部情報の取得エラーで
     * 美咲とのチャットそのものを
     *止めない。
     */
    return [];
  }
}

